fn splice(dest: &mut Vec[Int], src: &Vec[Int], pos: Int) -> Unit {
  var i = 0;
  while i < src.len() {
    dest.insert(pos + i, src[i]);
    i = i + 1;
  }
}

fn remove_range(v: &mut Vec[Int], start: Int, end: Int) -> Unit {
  var count = 0;
  while count < end - start {
    v.remove(start);
    count = count + 1;
  }
}

fn main() -> Int {
  var v = Vec[Int]();
  v.push(1); v.push(5); v.push(6); v.push(2);
  let insert_vals = Vec[Int]();
  insert_vals.push(2); insert_vals.push(3); insert_vals.push(4);
  splice(&mut v, &insert_vals, 1);
  return v[2];
}
